#pragma once
// Bounded offline rich-text lifecycle check. No database/account/real note.
static int runOrdinaryWorkflow(QTemporaryDir& root,const QString& resources,const QString& output){
 QFile marker(output+"/.wiz-synthetic-ordinary-workflow");if(!marker.open(QIODevice::ReadOnly)||marker.readAll()!="synthetic-only\n")return 4;
 int checks=0,failures=0;const auto check=[&](bool ok,const char* label){++checks;failures+=!ok;qInfo().noquote()<<(ok?"PASS":"FAIL")<<label;return ok;};
 QWebEngineProfile profile;profile.setCachePath(root.filePath("ordinary-cache"));profile.setPersistentStoragePath(root.filePath("ordinary-profile"));LocalOnly local;profile.setUrlRequestInterceptor(&local);
 QWebEngineView view;view.setAttribute(Qt::WA_DontShowOnScreen);view.resize(1000,700);auto* page=new QWebEnginePage(&profile,&view);view.setPage(page);QWebChannel channel;Bridge editor,explorer;channel.registerObject("WizQtEditor",&editor);channel.registerObject("WizExplorerApp",&explorer);page->setWebChannel(&channel);
 editor.original="<!doctype html><html><head><meta charset='utf-8'></head><body><h1>合成普通笔记</h1><p id='text'>普通正文 中文 😀</p><ul><li>项目一</li><li>项目二</li></ul><p><a href='https://example.invalid/'>合成链接</a></p></body></html>";
 QString html=editor.original,scripts;for(const auto& name:QStringList{"webengine/wizwebchannel.js","wizeditor/wizEditorForMac.js","wizeditor/dependency/marked/marked.umd.js","wizeditor/latexTheorems.js","wizeditor/markdownEnvironments.js","wizeditor/editorHelper.js"})scripts+="<script name='wiz_inner_script' wiz_style='unsave' src='"+QUrl::fromLocalFile(resources+name).toString().toHtmlEscaped()+"'></script>";
 html.insert(html.lastIndexOf("</body>"),scripts);QFile fixture(root.filePath("ordinary.html"));if(!fixture.open(QIODevice::WriteOnly))return 5;fixture.write(html.toUtf8());fixture.close();bool loaded=false,ok=false;auto connection=QObject::connect(&view,&QWebEngineView::loadFinished,[&](bool value){loaded=true;ok=value;});view.show();view.load(QUrl::fromLocalFile(fixture.fileName()));if(!check(wait([&]{return loaded;})&&ok,"local ordinary note fixture loads"))return 6;
 page->runJavaScript(WizDocumentPageReady::setupScript("'ordinary-workflow'","window.WizSpellCheckEnabled=false;window.WizNoteCss='';"+WizDocumentPageReady::initializeEditorScript(resources+"wizeditor/","zh-cn","synthetic-ordinary","Synthetic",false,"common")+"await new Promise(r=>WizEditor.off({reader:{type:'common'}},r));"));
 if(!check(wait([&]{return js(page,"window.WizNativeEditorSetup?.state==='ready'").toBool();}),"actual ordinary reader initializes"))return 7;
 check(js(page,"!document.body.isContentEditable&&document.body.innerText.includes('普通正文 中文 😀')&&document.querySelectorAll('li').length===2").toBool(),"ordinary text Unicode and list render");
 check(js(page,"!document.querySelector('.wiz-latex-theorem,mjx-container,.MathJax_SVG,.CodeMirror')").toBool(),"new frontend components do not convert ordinary rich text");
 js(page,"window.modeDone=false;WizPrepareNoteModeChange();WizEditor.on(null,()=>modeDone=true);");check(wait([&]{return js(page,"modeDone&&document.body.isContentEditable").toBool();}),"ordinary editing opens");
 check(js(page,"(()=>{const p=document.querySelector('#text')||document.querySelector('p');p.focus();const range=document.createRange();range.selectNodeContents(p);range.collapse(false);const s=getSelection();s.removeAllRanges();s.addRange(range);return document.execCommand('insertText',false,' 合成修改ABC');})()").toBool(),"standard rich-text insertion command responds");
 check(js(page,"document.body.innerText.includes('合成修改ABC')").toBool(),"inserted text visible");
 check(js(page,"document.execCommand('undo');!document.body.innerText.includes('合成修改ABC')").toBool(),"ordinary undo restores original text");
 check(js(page,"document.execCommand('redo');document.body.innerText.includes('合成修改ABC')").toBool(),"ordinary redo restores edit");
 const auto saved=WizDocumentSaveSnapshot::parse(js(page,WizDocumentSaveSnapshot::editorScript(true,false)));
 check(saved.state==WizDocumentSaveSnapshot::State::Changed&&saved.html.contains(QStringLiteral("合成修改ABC"))&&saved.html.contains(QStringLiteral("😀")),"actual editor save snapshot includes new text and Unicode");
 check(!saved.html.contains("<mjx-container")&&!saved.html.contains("wiz_inner_script")&&saved.html.contains("<li>")&&saved.html.contains("https://example.invalid/"),"save snapshot preserves list and link without generated frontend markup");
 const auto savedFile=root.filePath("ordinary-saved.html");check(WizDocumentSaveSnapshot::writeHtmlFile(savedFile,saved.html),"actual atomic HTML snapshot writer succeeds on synthetic path");QFile readback(savedFile);check(readback.open(QIODevice::ReadOnly)&&readback.readAll()==QByteArray::fromHex("efbbbf")+saved.html.toUtf8(),"saved UTF8 BOM and bytes read back exactly");
 js(page,"window.modeDone=false;WizPrepareNoteModeChange();WizEditor.off({reader:{type:'common'}},()=>modeDone=true);");check(wait([&]{return js(page,"modeDone&&!document.body.isContentEditable").toBool();})&&js(page,"document.body.innerText.includes('合成修改ABC')").toBool(),"ordinary return to reading preserves edit");
 const QString before=js(page,"document.documentElement.outerHTML").toString();const auto unchanged=WizDocumentSaveSnapshot::parse(js(page,WizDocumentSaveSnapshot::readerScript(false)));
 check(unchanged.state!=WizDocumentSaveSnapshot::State::Failed&&js(page,"document.documentElement.outerHTML").toString()==before,"reader snapshot leaves rendered DOM intact");
 QObject::disconnect(connection);loaded=false;ok=false;connection=QObject::connect(&view,&QWebEngineView::loadFinished,[&](bool value){loaded=true;ok=value;});view.load(QUrl::fromLocalFile(savedFile));check(wait([&]{return loaded;})&&ok&&js(page,"document.body.innerText.includes('合成修改ABC')&&document.querySelectorAll('li').length===2").toBool(),"saved ordinary HTML reopens with edited text and list");
 check(local.blocked.load()==0,"no network request or external link opened");check(!view.windowHandle()||!view.windowHandle()->isExposed(),"no native window exposed");
 const QJsonObject report{{"checks",checks},{"failures",failures},{"externalBlocked",local.blocked.load()},{"scope","ordinary rich-text public editor lifecycle and snapshot file only;not real DB save,sync,encryption or clipboard"}};QFile result(output+"/runtime.json");if(!result.open(QIODevice::WriteOnly|QIODevice::NewOnly))return 8;result.write(QJsonDocument(report).toJson(QJsonDocument::Indented));profile.setUrlRequestInterceptor(nullptr);return failures?9:0;
}
